"""LUNA-REL-01 rev2 deny hook: block any read inside a forbidden pattern."""
import os
import sys

FORBIDDEN = ("/sumo/", "/runs/", "_outcome/",
             "online_latency_baseline_v1/", "scenario_phase_profile_report_",
             "/scenarios_staging/")


def _hook(event, args):
    if event == "open" and args:
        try:
            path = os.fspath(args[0])
        except TypeError:
            return
        if isinstance(path, bytes):
            path = path.decode("utf-8", "replace")
        ap = os.path.abspath(str(path))
        for pat in FORBIDDEN:
            if pat in ap:
                raise PermissionError(f"BLOCKED forbidden-pattern access: {ap}")


sys.addaudithook(_hook)
